const request = $('When Executed by Another Workflow').first().json; const data = $input.first().json; const pool = (Array.isArray(data.images) ? data.images : []).slice(0, 3).map(img => ({ url: typeof img === 'string' ? img : img.url, caption: 'Ảnh từ kết quả tìm kiếm — chưa xác minh nguồn/quyền' + (typeof img !== 'string' && img.description ? ' (' + String(img.description).slice(0, 200) + ')' : ''), source_url: null, license_status: 'unknown' })).filter(img => img.url); const rows = (data.results || []).map(result => ({ json: { thread_id: request.thread_id, location_name: result.title || 'Địa điểm cần xác minh', district: null, address: null, pollution_type: 'chưa phân loại', summary: String(result.content || '').slice(0, 3000), observed_at: result.published_date || null, confidence: result.score >= 0.75 ? 'high' : result.score >= 0.45 ? 'medium' : 'low', sources: [{ title: result.title, url: result.url, published_at: result.published_date || null }], images: pool } }));
if (!rows.length) return [{ json: { no_results: true } }];
return rows;

const rows = $input.all().map(item => item.json).filter(row => row.id);
if (!rows.length) return [{ json: { status: 'no_results', findings: [], message: 'Không tìm thấy nguồn phù hợp. Thử từ khóa khác hoặc mở rộng khoảng thời gian.' } }];
return [{ json: { status: 'ok', findings: rows.map(row => ({ ...row, finding_id: row.id })) } }];
